23	                : owner.getLastName().trim().replaceAll("\\s+", " ").toLowerCase();
24	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
25	        try {
26	            byte[] digest = MessageDigest.getInstance("SHA-256")
27	                    .digest((lastName + '|' + postcode).getBytes(StandardCharsets.UTF_8));
28	            return HexFormat.of().formatHex(digest).substring(0, 12).toUpperCase();
29	        } catch (NoSuchAlgorithmException ex) {
30	            throw new IllegalStateException(ex);
